dashboard.definition:
{
  "title": "Place",
  "description": "Temperature, rain, wind, and soil for one place.",
  "visualizations": {
    "viz_temp_now": {
      "type": "splunk.singlevalue",
      "title": "Temperature now",
      "dataSources": {
        "primary": "ds_temp_now"
      },
      "options": {
        "unit": "F",
        "numberPrecision": 1,
        "majorColor": "#1B5E20"
      }
    },
    "viz_wind_now": {
      "type": "splunk.singlevalue",
      "title": "Wind now",
      "dataSources": {
        "primary": "ds_wind_now"
      },
      "options": {
        "unit": "mph",
        "numberPrecision": 1
      }
    },
    "viz_rain_today": {
      "type": "splunk.singlevalue",
      "title": "Rain today",
      "dataSources": {
        "primary": "ds_rain_today"
      },
      "options": {
        "unit": "in",
        "numberPrecision": 3
      }
    },
    "viz_high": {
      "type": "splunk.singlevalue",
      "title": "High today",
      "dataSources": {
        "primary": "ds_high"
      },
      "options": {
        "unit": "F",
        "numberPrecision": 1
      }
    },
    "viz_low": {
      "type": "splunk.singlevalue",
      "title": "Low today",
      "dataSources": {
        "primary": "ds_low"
      },
      "options": {
        "unit": "F",
        "numberPrecision": 1
      }
    },
    "viz_temp": {
      "type": "splunk.line",
      "title": "Air temperature",
      "dataSources": {
        "primary": "ds_temp"
      },
      "options": {
        "yAxisTitleText": "F",
        "legendDisplay": "off"
      }
    },
    "viz_rain": {
      "type": "splunk.column",
      "title": "Daily rain",
      "dataSources": {
        "primary": "ds_rain"
      },
      "options": {
        "yAxisTitleText": "inches",
        "legendDisplay": "off",
        "seriesColors": [
          "#1B5E20"
        ],
        "dataValuesDisplay": "all"
      }
    },
    "viz_wind": {
      "type": "splunk.line",
      "title": "Wind speed",
      "dataSources": {
        "primary": "ds_wind"
      },
      "options": {
        "yAxisTitleText": "mph",
        "legendDisplay": "off"
      }
    },
    "viz_soil_m": {
      "type": "splunk.line",
      "title": "Soil moisture",
      "dataSources": {
        "primary": "ds_soil_m"
      },
      "options": {
        "yAxisTitleText": "percent",
        "legendDisplay": "bottom"
      }
    },
    "viz_soil_t": {
      "type": "splunk.line",
      "title": "Soil temperature",
      "dataSources": {
        "primary": "ds_soil_t"
      },
      "options": {
        "yAxisTitleText": "F",
        "legendDisplay": "bottom"
      }
    }
  },
  "dataSources": {
    "ds_places": {
      "type": "ds.search",
      "name": "Places",
      "options": {
        "query": "| inputlookup ranch_places | table display_name | sort display_name",
        "queryParameters": {
          "earliest": "-5m",
          "latest": "now"
        }
      }
    },
    "ds_temp_now": {
      "type": "ds.search",
      "name": "Temp now",
      "options": {
        "query": "search `zentra_named(Air Temperature)` | `zentra_with_place` | where place=\"$place$\" | stats latest(value) as temp",
        "queryParameters": {
          "earliest": "-2d",
          "latest": "now"
        }
      }
    },
    "ds_wind_now": {
      "type": "ds.search",
      "name": "Wind now",
      "options": {
        "query": "search `zentra_named(Wind Speed)` | `zentra_with_place` | where place=\"$place$\" | stats latest(value) as wind",
        "queryParameters": {
          "earliest": "-2d",
          "latest": "now"
        }
      }
    },
    "ds_rain_today": {
      "type": "ds.search",
      "name": "Rain today",
      "options": {
        "query": "search `zentra_precip_by_interval` | where place=\"$place$\" AND logger_day=strftime(now(), \"%Y-%m-%d\") | stats sum(value) as inches",
        "queryParameters": {
          "earliest": "-2d@d",
          "latest": "now"
        }
      }
    },
    "ds_high": {
      "type": "ds.search",
      "name": "High",
      "options": {
        "query": "search `zentra_named(Max Air Temperature)` | `zentra_with_place` | where place=\"$place$\" AND logger_day=strftime(now(), \"%Y-%m-%d\") | stats max(value) as high",
        "queryParameters": {
          "earliest": "-2d@d",
          "latest": "now"
        }
      }
    },
    "ds_low": {
      "type": "ds.search",
      "name": "Low",
      "options": {
        "query": "search `zentra_named(Min Air Temperature)` | `zentra_with_place` | where place=\"$place$\" AND logger_day=strftime(now(), \"%Y-%m-%d\") | stats min(value) as low",
        "queryParameters": {
          "earliest": "-2d@d",
          "latest": "now"
        }
      }
    },
    "ds_temp": {
      "type": "ds.search",
      "name": "Temp chart",
      "options": {
        "query": "search `zentra_named(Air Temperature)` | `zentra_with_place` | where place=\"$place$\" | timechart span=15m avg(value) as temp_f",
        "queryParameters": {
          "earliest": "-7d",
          "latest": "now"
        }
      }
    },
    "ds_rain": {
      "type": "ds.search",
      "name": "Rain chart",
      "options": {
        "query": "search `zentra_precip_by_interval`\n| where place=\"$place$\"\n| stats sum(value) as inches by logger_day\n| eval inches=if(inches>0, round(inches, 3), null())\n| where isnotnull(inches)\n| eval _time=strptime(logger_day.\" 12:00:00\", \"%Y-%m-%d %H:%M:%S\")\n| table _time inches",
        "queryParameters": {
          "earliest": "-30d@d",
          "latest": "now"
        }
      }
    },
    "ds_wind": {
      "type": "ds.search",
      "name": "Wind chart",
      "options": {
        "query": "search `zentra_named(Wind Speed)` | `zentra_with_place` | where place=\"$place$\" | timechart span=15m avg(value) as wind_mph",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_soil_m": {
      "type": "ds.search",
      "name": "Soil moisture",
      "options": {
        "query": "search `zentra_named(Water Content)` | `zentra_with_place` | where place=\"$place$\"\n| eval sensor=\"Port \".port_number\n| timechart span=1h avg(value) by sensor",
        "queryParameters": {
          "earliest": "-7d",
          "latest": "now"
        }
      }
    },
    "ds_soil_t": {
      "type": "ds.search",
      "name": "Soil temperature",
      "options": {
        "query": "search `zentra_named(Soil Temperature)` | `zentra_with_place` | where place=\"$place$\"\n| eval sensor=\"Port \".port_number\n| timechart span=1h avg(value) by sensor",
        "queryParameters": {
          "earliest": "-7d",
          "latest": "now"
        }
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {}
        }
      }
    }
  },
  "inputs": {
    "input_place": {
      "type": "input.dropdown",
      "title": "Place",
      "options": {
        "token": "place",
        "selectFirstSearchResult": true,
        "items": "> frame(label, value) | objects()"
      },
      "dataSources": {
        "primary": "ds_places"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "label": "> primary | seriesByName(\"display_name\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": "> primary | seriesByName(\"display_name\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "layout": {
    "tabs": {
      "items": [
        {
          "layoutId": "layout_1",
          "label": "Ranch"
        }
      ]
    },
    "layoutDefinitions": {
      "layout_1": {
        "type": "grid",
        "options": {
          "width": 1440,
          "height": 1100,
          "display": "auto-scale"
        },
        "structure": [
          {
            "item": "viz_temp_now",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 288,
              "h": 140
            }
          },
          {
            "item": "viz_wind_now",
            "type": "block",
            "position": {
              "x": 288,
              "y": 0,
              "w": 288,
              "h": 140
            }
          },
          {
            "item": "viz_rain_today",
            "type": "block",
            "position": {
              "x": 576,
              "y": 0,
              "w": 288,
              "h": 140
            }
          },
          {
            "item": "viz_high",
            "type": "block",
            "position": {
              "x": 864,
              "y": 0,
              "w": 288,
              "h": 140
            }
          },
          {
            "item": "viz_low",
            "type": "block",
            "position": {
              "x": 1152,
              "y": 0,
              "w": 288,
              "h": 140
            }
          },
          {
            "item": "viz_temp",
            "type": "block",
            "position": {
              "x": 0,
              "y": 160,
              "w": 720,
              "h": 300
            }
          },
          {
            "item": "viz_rain",
            "type": "block",
            "position": {
              "x": 720,
              "y": 160,
              "w": 720,
              "h": 300
            }
          },
          {
            "item": "viz_wind",
            "type": "block",
            "position": {
              "x": 0,
              "y": 480,
              "w": 1440,
              "h": 280
            }
          },
          {
            "item": "viz_soil_m",
            "type": "block",
            "position": {
              "x": 0,
              "y": 780,
              "w": 720,
              "h": 300
            }
          },
          {
            "item": "viz_soil_t",
            "type": "block",
            "position": {
              "x": 720,
              "y": 780,
              "w": 720,
              "h": 300
            }
          }
        ]
      }
    },
    "globalInputs": [
      "input_place"
    ]
  }
}
